import { componentAttrs } from "../_utils/component.helper";

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const ZOOM_IN_SVG = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" aria-hidden="true" focusable="false"><circle cx="10" cy="10" r="7" stroke="currentColor" stroke-width="2"/><line x1="15" y1="15" x2="21" y2="21" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><line x1="7" y1="10" x2="13" y2="10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><line x1="10" y1="7" x2="10" y2="13" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';
const ZOOM_OUT_SVG = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" aria-hidden="true" focusable="false"><circle cx="10" cy="10" r="7" stroke="currentColor" stroke-width="2"/><line x1="15" y1="15" x2="21" y2="21" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><line x1="7" y1="10" x2="13" y2="10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';

// Not editor-configurable any more -- the manifest only exposes `imageSources`/`imageFolder`.
const GRID_COLUMNS = 4;
const GRID_GAP = 16;
const GRID_ASPECT_RATIO = '320 / 240';

/**
 * CONTENT_API_URL -- a Matrix REST resource acting as an authenticated
 * Content API proxy, confirmed working via the `content-api-picker` debug
 * component -- returns each child's {id, name, url, metadata}, read via the
 * same `rootId` query param convention as the Asset Listing feed this
 * replaced. No fallback: if the env var isn't set, the folder contributes no
 * images (see resolveFolderImages), same as any other resolution failure.
 */
const ROOT_ID_PARAM_NAME = 'rootId';

function resolveImage(image) {
  if (!image) return { url: '', thumbUrl: '', alt: '', caption: '', width: null, height: null };
  if (typeof image === 'string') return { url: image, thumbUrl: image, alt: '', caption: '', width: null, height: null };

  // Per the real SquizImage schema: imageVariations.original is a single
  // object, but small/medium/large are each arrays of variations, not a
  // single object -- there is no "thumbnail" key at all.
  const variations = image.imageVariations || {};
  const original = variations.original || {};
  const thumb = variations.small?.[0] || original;

  return {
    url: original.url || '',
    thumbUrl: thumb.url || original.url || '',
    alt: image.alt || image.name || '',
    caption: image.caption || '',
    width: original.width || null,
    height: original.height || null,
  };
}

function parseAssetUriId(uri) {
  const match = /^matrix-asset:\/\/[a-zA-Z0-9.-]+\/(\d+)(?::.+)?$/.exec(String(uri ?? ''));
  return match ? match[1] : null;
}

/**
 * Maps one item from the CONTENT_API_URL feed into a gallery image. The
 * feed's exact shape is admin-configured in Matrix (a REST resource acting
 * as a Content API proxy), not schema-guaranteed by this codebase -- see
 * image-gallery.spec.md assumption 6. Only `url` is treated as required;
 * everything else degrades gracefully if absent. `cardDescription` is a
 * top-level array on this feed (confirmed live), not nested under a
 * `metadata` key like the previous Asset Listing feed was.
 */
function toGalleryImageFromListing(item) {
  if (!item || !item.url) return null;

  const caption = Array.isArray(item.cardDescription) ? item.cardDescription[0] : '';

  return {
    url: item.url,
    thumbUrl: item.url,
    alt: item.name || '',
    caption: caption || '',
    width: null,
    height: null,
  };
}

/**
 * Fetches the `imageFolder` field's children via CONTENT_API_URL -- a plain
 * unauthenticated fetch(), not info.fns (which has no children-listing
 * capability at all on this tenant, see assumption 3). Any failure (no
 * folder selected, bad URI, env var unset, network error, non-JSON
 * response) contributes zero images rather than throwing.
 */
async function resolveFolderImages(imageFolder, contentApiUrl) {
  const folderId = parseAssetUriId(imageFolder);
  if (!folderId || !contentApiUrl) return [];

  const url = `${contentApiUrl}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(folderId)}`;

  let body;
  try {
    const res = await fetch(url);
    if (!res.ok) return [];
    body = await res.json();
  } catch {
    return [];
  }

  if (!Array.isArray(body)) return [];
  return body.map(toGalleryImageFromListing).filter(Boolean);
}

/**
 * A resolved Matrix asset is NOT necessarily SquizImage-shaped -- that
 * strict shape only applies to component *input* validation. What a live
 * resolveUri()/resolveMatrixAssetById() call actually returns for a plain
 * asset is unconfirmed (unverified against a real Matrix backend -- see
 * spec assumption). This defensively accepts either shape: a full
 * SquizImage (imageVariations.original.url present) or a generic asset
 * object with a plain url/name.
 */
function toGalleryImage(asset) {
  if (!asset) return null;
  if (asset.imageVariations?.original?.url) return resolveImage(asset);

  const url = asset.url || (Array.isArray(asset.urls) ? asset.urls[0] : '') || '';
  if (!url) return null;

  return {
    url,
    thumbUrl: url,
    alt: asset.alt || asset.name || asset.short_name || '',
    caption: asset.caption || asset.name || '',
    width: null,
    height: null,
  };
}

/**
 * Resolves the `imageSources` manifest field (an array of matrix-asset-uri
 * strings picked via Squiz's normal asset picker, one or more individually
 * selected images) into a flat list of gallery images. Each source resolves
 * independently and in parallel, contributing one image. Any source that
 * fails to resolve (or `info.fns` not being available at all) contributes
 * nothing rather than throwing.
 */
async function resolveImages(imageSources, fns) {
  if (!Array.isArray(imageSources) || imageSources.length === 0) return [];
  if (typeof fns?.resolveUri !== 'function') return [];

  const resolvedLists = await Promise.all(imageSources.map(async (source) => {
    if (!source) return [];

    let resolved;
    try {
      resolved = await fns.resolveUri(source);
    } catch {
      return [];
    }
    if (!resolved) return [];

    const image = toGalleryImage(resolved);
    return image ? [image] : [];
  }));

  return resolvedLists.flat();
}

/**
 * Combines individually-picked images (`imageSources`) with every image
 * inside the picked folder (`imageFolder`), de-duplicated by URL in case the
 * same image is reachable both ways.
 */
async function resolveAllImages(imageSources, imageFolder, fns, contentApiUrl) {
  const [sourceImages, folderImages] = await Promise.all([
    resolveImages(imageSources, fns),
    resolveFolderImages(imageFolder, contentApiUrl),
  ]);

  const seenUrls = new Set();
  return [...sourceImages, ...folderImages].filter((image) => {
    if (seenUrls.has(image.url)) return false;
    seenUrls.add(image.url);
    return true;
  });
}

export default {
  async main(input = {}, info = {}) {
    const { imageSources = [], imageFolder = '' } = input;

    const items = await resolveAllImages(imageSources, imageFolder, info.fns, info.env?.CONTENT_API_URL);

    const galleryStyle = `--gallery-columns: ${GRID_COLUMNS}; --gallery-gap: ${GRID_GAP}px; --gallery-aspect-ratio: ${GRID_ASPECT_RATIO};`;

    const gridItemsHtml = items.map((item, index) => {
      const overlayHtml = item.caption
        ? `<span class="image-gallery__overlay"><span class="image-gallery__overlay-caption">${esc(item.caption)}</span></span>`
        : '';

      return `
      <button type="button" class="image-gallery__item" data-gallery-index="${index}" aria-label="Open image ${index + 1}${item.alt ? `: ${esc(item.alt)}` : ''}">
        <img class="image-gallery__thumb" src="${esc(item.thumbUrl)}" alt="${esc(item.alt)}" loading="lazy" data-gallery-loading${item.width ? ` width="${item.width}"` : ''}${item.height ? ` height="${item.height}"` : ''} />
        ${overlayHtml}
      </button>`;
    }).join('');

    const hasMultiple = items.length > 1;

    const slidesHtml = items.map((item, index) => {
      const captionHtml = item.caption
        ? `<figcaption class="image-gallery-lightbox__caption"><p class="image-gallery-lightbox__title">${esc(item.caption)}</p></figcaption>`
        : '';

      return `
      <figure class="image-gallery-lightbox__slide" data-slide-index="${index}"${index === 0 ? '' : ' hidden'}>
        <img class="image-gallery-lightbox__image" src="${esc(item.url)}" alt="${esc(item.alt)}"${item.width ? ` width="${item.width}"` : ''}${item.height ? ` height="${item.height}"` : ''} />
        ${captionHtml}
      </figure>`;
    }).join('');

    const thumbnailsHtml = hasMultiple
      ? items.map((item, index) => `
      <button type="button" class="image-gallery-lightbox__thumbnail-button${index === 0 ? ' image-gallery-lightbox__thumbnail-button--selected' : ''}" data-thumbnail-index="${index}" aria-label="Go to image ${index + 1}">
        <img class="image-gallery-lightbox__thumbnail-image" src="${esc(item.thumbUrl)}" alt="" />
      </button>`).join('')
      : '';

    const navHtml = hasMultiple
      ? `<button type="button" class="image-gallery-lightbox__nav-prev" aria-label="Previous image">&#8249;</button>`
      : '';
    const navNextHtml = hasMultiple
      ? `<button type="button" class="image-gallery-lightbox__nav-next" aria-label="Next image">&#8250;</button>`
      : '';

    return /*html*/`
<div ${componentAttrs("image-gallery", input)} class="image-gallery-root">
  <div class="image-gallery" style="${galleryStyle}">
    ${gridItemsHtml}
  </div>

  <div class="image-gallery-lightbox" data-image-gallery-lightbox hidden role="dialog" aria-modal="true" aria-label="Image viewer">
    <div class="image-gallery-lightbox__container">
      <div class="image-gallery-lightbox__header">
        <span class="image-gallery-lightbox__counter"><span data-lightbox-current>1</span> / ${items.length}</span>
        <div class="image-gallery-lightbox__controls">
          <button type="button" class="image-gallery-lightbox__zoom-out" data-zoom-out aria-label="Zoom out" disabled>${ZOOM_OUT_SVG}</button>
          <button type="button" class="image-gallery-lightbox__zoom-in" data-zoom-in aria-label="Zoom in">${ZOOM_IN_SVG}</button>
          <button type="button" class="image-gallery-lightbox__close" aria-label="Close image viewer">&#10005;</button>
        </div>
      </div>
      <div class="image-gallery-lightbox__main">
        ${navHtml}
        <div class="image-gallery-lightbox__viewer">
          ${slidesHtml}
        </div>
        ${navNextHtml}
      </div>
      ${hasMultiple ? `<div class="image-gallery-lightbox__thumbnails">${thumbnailsHtml}</div>` : ''}
    </div>
  </div>
</div>
`;
  },
};
